insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('brand-assets','brand-assets',false,15728640,array['application/pdf','image/png','image/jpeg','image/webp','image/svg+xml','font/ttf','font/otf','font/woff','font/woff2']) on conflict(id) do nothing;
-- Object path format: workspace_uuid/brand_uuid/filename
create policy "workspace members read brand files" on storage.objects for select to authenticated using(bucket_id='brand-assets' and public.is_workspace_member(((storage.foldername(name))[1])::uuid));
create policy "workspace editors upload brand files" on storage.objects for insert to authenticated with check(bucket_id='brand-assets' and public.has_workspace_role(((storage.foldername(name))[1])::uuid,array['owner','admin','editor']::public.workspace_role[]));
create policy "workspace editors update brand files" on storage.objects for update to authenticated using(bucket_id='brand-assets' and public.has_workspace_role(((storage.foldername(name))[1])::uuid,array['owner','admin','editor']::public.workspace_role[])) with check(bucket_id='brand-assets' and public.has_workspace_role(((storage.foldername(name))[1])::uuid,array['owner','admin','editor']::public.workspace_role[]));
create policy "workspace admins delete brand files" on storage.objects for delete to authenticated using(bucket_id='brand-assets' and public.has_workspace_role(((storage.foldername(name))[1])::uuid,array['owner','admin']::public.workspace_role[]));